on conflict (source, symbol, trade_date) do update set
  open = excluded.open,
  high = excluded.high,
  low = excluded.low,
  close = excluded.close,
  volume = excluded.volume,
  raw = excluded.raw,
  fetched_at = excluded.fetched_at;

